package api

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/idempotency-gateway/internal/store"
)

const (
	codeFingerprintConflict = "idempotency_fingerprint_conflict"
	codeInvalidRecord       = "invalid_idempotency_record"
	codeNotFound            = "not_found"
	codeInvalidCursor       = "invalid_cursor"
	codeStorageUnavailable  = "storage_unavailable"

	defaultPageLimit = 50
	maxPageLimit     = 100
)

// submitRequest is the only accepted body for record submission. Times are RFC 3339 UTC strings;
// response_snapshot is any JSON value and is replayed byte-for-byte as stored.
type submitRequest struct {
	IdempotencyKey     string          `json:"idempotency_key"`
	RequestFingerprint string          `json:"request_fingerprint"`
	ResponseSnapshot   json.RawMessage `json:"response_snapshot"`
	ExpiresAt          *string         `json:"expires_at"`
}

// validatedSubmitRequest carries the normalized fields of an accepted submission.
type validatedSubmitRequest struct {
	idempotencyKey     string
	requestFingerprint string
	responseSnapshot   json.RawMessage
	expiresAt          time.Time
}

// validateSubmitRequest enforces the fixed submission contract. The message return value carries
// the fixed message for InvalidIdempotencyRequest. Expiry must be strictly later than now: a
// timestamp equal to the creation moment is already expired and is rejected.
func validateSubmitRequest(rawBody []byte, now time.Time) (validatedSubmitRequest, string, bool) {
	var request submitRequest
	if err := json.Unmarshal(rawBody, &request); err != nil {
		return validatedSubmitRequest{}, "request body must be a single JSON object", false
	}
	if strings.TrimSpace(request.IdempotencyKey) == "" {
		return validatedSubmitRequest{}, "idempotency_key must not be empty", false
	}
	if strings.TrimSpace(request.RequestFingerprint) == "" {
		return validatedSubmitRequest{}, "request_fingerprint must not be empty", false
	}
	if request.ExpiresAt == nil || strings.TrimSpace(*request.ExpiresAt) == "" {
		return validatedSubmitRequest{}, "expires_at must be provided", false
	}
	expiresAt, err := time.Parse(time.RFC3339Nano, strings.TrimSpace(*request.ExpiresAt))
	if err != nil {
		return validatedSubmitRequest{}, "expires_at must be an RFC 3339 timestamp", false
	}
	expiresAt = expiresAt.UTC()
	if !expiresAt.After(now) {
		return validatedSubmitRequest{}, "expires_at must be later than the current time", false
	}
	snapshot := request.ResponseSnapshot
	if len(snapshot) == 0 {
		snapshot = json.RawMessage("null")
	}
	if !isValidJSON(snapshot) {
		return validatedSubmitRequest{}, "response_snapshot must be valid JSON", false
	}
	return validatedSubmitRequest{
		idempotencyKey:     request.IdempotencyKey,
		requestFingerprint: request.RequestFingerprint,
		responseSnapshot:   snapshot,
		expiresAt:          expiresAt,
	}, "", true
}

// recordResponse lists its fields in the fixed order every record-shaped result uses.
type recordResponse struct {
	ID                 string          `json:"id"`
	IdempotencyKey     string          `json:"idempotency_key"`
	Status             string          `json:"status"`
	RequestFingerprint string          `json:"request_fingerprint"`
	ResponseSnapshot   json.RawMessage `json:"response_snapshot"`
	CreatedAt          string          `json:"created_at"`
	ExpiresAt          string          `json:"expires_at"`
}

type recordEnvelope struct {
	Record recordResponse `json:"record"`
}

type listResponse struct {
	Records    []recordResponse `json:"records"`
	NextCursor string           `json:"next_cursor"`
}

type conflictBody struct {
	Code               string `json:"code"`
	Message            string `json:"message"`
	RecordID           string `json:"record_id"`
	RequestFingerprint string `json:"request_fingerprint"`
}

type errorBody struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// pageCursor is the opaque continuation token. Only the last row's creation time and id are
// needed because ordering is (created_at DESC, id DESC).
type pageCursor struct {
	CreatedAt time.Time `json:"created_at"`
	ID        string    `json:"id"`
}

func (p pageCursor) encode() string {
	raw, _ := json.Marshal(p)
	return base64.RawURLEncoding.EncodeToString(raw)
}

func parsePageCursor(token string) (pageCursor, error) {
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimSpace(token))
	if err != nil {
		return pageCursor{}, err
	}
	var cursor pageCursor
	if err := json.Unmarshal(raw, &cursor); err != nil {
		return pageCursor{}, err
	}
	if cursor.ID == "" || cursor.CreatedAt.IsZero() {
		return pageCursor{}, errors.New("cursor missing fields")
	}
	return cursor, nil
}

func registerIdempotencyRoutes(router *gin.Engine, st *store.Store) {
	router.POST("/v1/idempotency/records", func(c *gin.Context) {
		handleSubmit(c, st)
	})
	router.GET("/v1/idempotency/records/:key", func(c *gin.Context) {
		handleGetRecord(c, st)
	})
	router.GET("/v1/idempotency/records", func(c *gin.Context) {
		handleListRecords(c, st)
	})
}

func handleSubmit(c *gin.Context, st *store.Store) {
	now := time.Now().UTC()

	rawBody, err := io.ReadAll(c.Request.Body)
	if err != nil || len(bytes.TrimSpace(rawBody)) == 0 {
		writeInvalidRecord(c, "request body must be a single JSON object")
		return
	}
	validated, message, ok := validateSubmitRequest(rawBody, now)
	if !ok {
		writeInvalidRecord(c, message)
		return
	}

	id, err := store.NewRecordID()
	if err != nil {
		writeStorageUnavailable(c)
		return
	}
	candidate := store.Record{
		ID:                 id,
		IdempotencyKey:     validated.idempotencyKey,
		RequestFingerprint: validated.requestFingerprint,
		ResponseSnapshot:   validated.responseSnapshot,
		CreatedAt:          now,
		ExpiresAt:          validated.expiresAt,
	}

	record, outcome, err := st.PutRecord(c.Request.Context(), candidate, now)
	if err != nil {
		writeStorageUnavailable(c)
		return
	}
	switch outcome {
	case store.PutConflict:
		c.JSON(http.StatusConflict, gin.H{"error": conflictBody{
			Code:               codeFingerprintConflict,
			Message:            "a record with this idempotency key exists but its request fingerprint differs",
			RecordID:           record.ID,
			RequestFingerprint: record.RequestFingerprint,
		}})
	default:
		// Both PutCreated and PutReplayed use the exact same success envelope, so a replay is
		// indistinguishable in shape from the first successful execution.
		c.JSON(http.StatusOK, recordEnvelope{Record: toRecordResponse(record)})
	}
}

func handleGetRecord(c *gin.Context, st *store.Store) {
	key := c.Param("key")
	if strings.TrimSpace(key) == "" {
		writeNotFound(c)
		return
	}
	record, err := st.ActiveRecordByKey(c.Request.Context(), key, time.Now().UTC())
	if err != nil {
		writeStorageUnavailable(c)
		return
	}
	if record == nil {
		writeNotFound(c)
		return
	}
	c.JSON(http.StatusOK, recordEnvelope{Record: toRecordResponse(record)})
}

func handleListRecords(c *gin.Context, st *store.Store) {
	now := time.Now().UTC()
	filter := store.ListFilter{Limit: defaultPageLimit}

	if key := strings.TrimSpace(c.Query("key")); key != "" {
		filter.IdempotencyKey = key
	}

	switch strings.TrimSpace(c.Query("status")) {
	case "", "active":
	case "expired":
	default:
		writeInvalidRecord(c, "status must be active or expired")
		return
	}

	if raw := strings.TrimSpace(c.Query("expires_before")); raw != "" {
		parsed, ok := parseQueryTime(c, raw)
		if !ok {
			return
		}
		filter.ExpiresBefore = &parsed
	}
	if raw := strings.TrimSpace(c.Query("expires_after")); raw != "" {
		parsed, ok := parseQueryTime(c, raw)
		if !ok {
			return
		}
		filter.ExpiresAfter = &parsed
	}

	if rawLimit := strings.TrimSpace(c.Query("limit")); rawLimit != "" {
		limit, ok := parseQueryLimit(c, rawLimit)
		if !ok {
			return
		}
		filter.Limit = limit
	}

	if rawCursor := strings.TrimSpace(c.Query("cursor")); rawCursor != "" {
		cursor, err := parsePageCursor(rawCursor)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": errorBody{
				Code:    codeInvalidCursor,
				Message: "pagination cursor is invalid",
			}})
			return
		}
		filter.CursorCreatedAt = cursor.CreatedAt
		filter.CursorID = cursor.ID
	}

	// Expired records never participate in normal results; the page is deterministically empty
	// rather than surfacing historical snapshots. Parameters above are still validated first.
	if strings.TrimSpace(c.Query("status")) == "expired" {
		c.JSON(http.StatusOK, listResponse{Records: []recordResponse{}, NextCursor: ""})
		return
	}

	// Fetch one extra row to decide whether another page exists without an unstable total count.
	filter.Limit++
	records, err := st.ListRecords(c.Request.Context(), filter, now)
	if err != nil {
		writeStorageUnavailable(c)
		return
	}

	nextCursor := ""
	if len(records) == filter.Limit {
		last := records[len(records)-2]
		nextCursor = pageCursor{CreatedAt: last.CreatedAt, ID: last.ID}.encode()
		records = records[:len(records)-1]
	}

	response := listResponse{Records: make([]recordResponse, 0, len(records))}
	for i := range records {
		response.Records = append(response.Records, toRecordResponse(&records[i]))
	}
	response.NextCursor = nextCursor
	c.JSON(http.StatusOK, response)
}

func parseQueryTime(c *gin.Context, raw string) (time.Time, bool) {
	parsed, err := time.Parse(time.RFC3339Nano, raw)
	if err != nil {
		writeInvalidRecord(c, "time filters must be RFC 3339 timestamps")
		return time.Time{}, false
	}
	return parsed.UTC(), true
}

func parseQueryLimit(c *gin.Context, raw string) (int, bool) {
	limit := 0
	for _, digit := range raw {
		if digit < '0' || digit > '9' {
			writeInvalidRecord(c, "limit must be a positive integer")
			return 0, false
		}
		limit = limit*10 + int(digit-'0')
		if limit > maxPageLimit {
			limit = maxPageLimit + 1
		}
	}
	if limit < 1 || limit > maxPageLimit {
		writeInvalidRecord(c, fmt.Sprintf("limit must be between 1 and %d", maxPageLimit))
		return 0, false
	}
	return limit, true
}

func toRecordResponse(record *store.Record) recordResponse {
	return recordResponse{
		ID:                 record.ID,
		IdempotencyKey:     record.IdempotencyKey,
		Status:             "active",
		RequestFingerprint: record.RequestFingerprint,
		ResponseSnapshot:   record.ResponseSnapshot,
		CreatedAt:          record.CreatedAt.Format(time.RFC3339Nano),
		ExpiresAt:          record.ExpiresAt.Format(time.RFC3339Nano),
	}
}

func isValidJSON(raw json.RawMessage) bool {
	var value any
	return json.Unmarshal(raw, &value) == nil
}

func writeInvalidRecord(c *gin.Context, message string) {
	c.JSON(http.StatusBadRequest, gin.H{"error": errorBody{Code: codeInvalidRecord, Message: message}})
}

func writeNotFound(c *gin.Context) {
	c.JSON(http.StatusNotFound, gin.H{"error": errorBody{
		Code:    codeNotFound,
		Message: "no active idempotency record exists for this key",
	}})
}

func writeStorageUnavailable(c *gin.Context) {
	c.JSON(http.StatusServiceUnavailable, gin.H{"error": errorBody{
		Code:    codeStorageUnavailable,
		Message: "database is not available",
	}})
}
// Package store owns the SQLite file and every write the service performs.
package store

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"errors"
	"time"
)

// Record is one idempotency record. Rows are immutable: a replay never overwrites the first
// snapshot and a record re-created after expiry inserts a fresh row instead of updating history.
type Record struct {
	ID                 string
	IdempotencyKey     string
	RequestFingerprint string
	ResponseSnapshot   []byte
	CreatedAt          time.Time
	ExpiresAt          time.Time
}

// PutOutcome tells the caller which branch PutRecord took.
type PutOutcome int

const (
	// PutCreated means the candidate was inserted as the first record for its key.
	PutCreated PutOutcome = iota
	// PutReplayed means an active record with the same fingerprint was returned.
	PutReplayed
	// PutConflict means an active record with a different fingerprint was returned.
	PutConflict
)

// ErrInvalidID is returned when a pagination cursor references a malformed record id.
var ErrInvalidID = errors.New("invalid record id")

// NewRecordID generates the public identifier attached to every stored record. The shape is
// fixed ("rec_" followed by 32 lowercase hex characters) so callers can rely on it.
func NewRecordID() (string, error) {
	raw := make([]byte, 16)
	if _, err := rand.Read(raw); err != nil {
		return "", err
	}
	return "rec_" + hex.EncodeToString(raw), nil
}

// PutRecord stores the candidate unless an active (non-expired) record already owns the same
// idempotency key at now. With an existing active record the outcome is PutReplayed when the
// fingerprints match and PutConflict otherwise; in both cases the returned record is the stored
// one and the candidate is not written.
//
// The whole check-then-insert flow runs in one BEGIN IMMEDIATE transaction, and writeMu also
// serializes writers within this instance. Across processes sharing the same file, SQLite grants
// the RESERVED lock to only one connection at a time (peers wait on busy_timeout), so concurrent
// submissions for one key elect exactly one visible winner: matching fingerprints all replay that
// winner, different fingerprints only see it after the winner commits, and a re-submission once
// every row has expired inserts one fresh row while leaving the historical rows untouched.
func (s *Store) PutRecord(ctx context.Context, candidate Record, now time.Time) (*Record, PutOutcome, error) {
	nowNS := now.UnixNano()

	s.writeMu.Lock()
	defer s.writeMu.Unlock()

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return nil, 0, err
	}
	defer tx.Rollback()

	existing, err := queryActiveRecord(ctx, tx, candidate.IdempotencyKey, nowNS)
	if err != nil {
		return nil, 0, err
	}
	if existing != nil {
		if existing.RequestFingerprint == candidate.RequestFingerprint {
			return existing, PutReplayed, nil
		}
		return existing, PutConflict, nil
	}

	if _, err := tx.ExecContext(ctx, `
INSERT INTO idempotency_records
	(id, idempotency_key, request_fingerprint, response_snapshot, created_at_ns, expires_at_ns)
VALUES (?, ?, ?, ?, ?, ?)`,
		candidate.ID,
		candidate.IdempotencyKey,
		candidate.RequestFingerprint,
		string(candidate.ResponseSnapshot),
		candidate.CreatedAt.UnixNano(),
		candidate.ExpiresAt.UnixNano(),
	); err != nil {
		return nil, 0, err
	}
	if err := tx.Commit(); err != nil {
		return nil, 0, err
	}
	return &candidate, PutCreated, nil
}

// ActiveRecordByKey returns the non-expired record for key at now, or (nil, nil) when the key is
// unknown or every record for it has expired. Expired rows never leak through this lookup.
func (s *Store) ActiveRecordByKey(ctx context.Context, key string, now time.Time) (*Record, error) {
	return queryActiveRecord(ctx, s.db, key, now.UnixNano())
}

// ListFilter narrows ListRecords. Zero-valued fields are not applied.
type ListFilter struct {
	IdempotencyKey  string
	ExpiresBefore   *time.Time
	ExpiresAfter    *time.Time
	CursorCreatedAt time.Time
	CursorID        string
	Limit           int
}

// ListRecords returns active records matching filter, newest first with id as the deterministic
// tie-breaker. Expired records never participate. The cursor points at the last row of the
// previous page and only strictly earlier rows are returned, so inserts during paging never
// reshuffle earlier pages.
func (s *Store) ListRecords(ctx context.Context, filter ListFilter, now time.Time) ([]Record, error) {
	query := `
SELECT id, idempotency_key, request_fingerprint, response_snapshot, created_at_ns, expires_at_ns
FROM idempotency_records
WHERE expires_at_ns > ?`
	args := []any{now.UnixNano()}

	if filter.IdempotencyKey != "" {
		query += ` AND idempotency_key = ?`
		args = append(args, filter.IdempotencyKey)
	}
	if filter.ExpiresBefore != nil {
		query += ` AND expires_at_ns < ?`
		args = append(args, filter.ExpiresBefore.UnixNano())
	}
	if filter.ExpiresAfter != nil {
		query += ` AND expires_at_ns > ?`
		args = append(args, filter.ExpiresAfter.UnixNano())
	}
	if !filter.CursorCreatedAt.IsZero() && filter.CursorID != "" {
		query += ` AND (created_at_ns < ? OR (created_at_ns = ? AND id < ?))`
		args = append(args, filter.CursorCreatedAt.UnixNano(), filter.CursorCreatedAt.UnixNano(), filter.CursorID)
	}

	limit := filter.Limit
	if limit <= 0 {
		limit = defaultListLimit
	}
	query += ` ORDER BY created_at_ns DESC, id DESC LIMIT ?`
	args = append(args, limit)

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	records := make([]Record, 0)
	for rows.Next() {
		record, err := scanRecord(rows)
		if err != nil {
			return nil, err
		}
		records = append(records, *record)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return records, nil
}

const defaultListLimit = 50

type rowQuerier interface {
	QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
}

const activeRecordQuery = `
SELECT id, idempotency_key, request_fingerprint, response_snapshot, created_at_ns, expires_at_ns
FROM idempotency_records
WHERE idempotency_key = ? AND expires_at_ns > ?
ORDER BY created_at_ns DESC, id DESC
LIMIT 1`

func queryActiveRecord(ctx context.Context, querier rowQuerier, key string, nowNS int64) (*Record, error) {
	record, err := scanRecord(querier.QueryRowContext(ctx, activeRecordQuery, key, nowNS))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return record, nil
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scanRecord(scanner rowScanner) (*Record, error) {
	var record Record
	var snapshot string
	var createdNS, expiresNS int64
	if err := scanner.Scan(
		&record.ID,
		&record.IdempotencyKey,
		&record.RequestFingerprint,
		&snapshot,
		&createdNS,
		&expiresNS,
	); err != nil {
		return nil, err
	}
	record.ResponseSnapshot = []byte(snapshot)
	record.CreatedAt = time.Unix(0, createdNS).UTC()
	record.ExpiresAt = time.Unix(0, expiresNS).UTC()
	return &record, nil
}

